update orders
set status = 2, pay_status = 1, checkout_time = #{checkoutTime}
where id = #{id} and status = 1

update orders
set status = 4, verify_time = #{verifyTime}, service_start_time = #{verifyTime}
where id = #{id} and status = 3

update orders
set status = 5, service_end_time = #{serviceEndTime}
where id = #{id} and status = 4

update orders
set status = 6,
    cancel_reason = #{cancelReason},
    cancel_time = #{cancelTime}

        , pay_status = 2

where id = #{id} and status = #{fromStatus}

mapper.select:
select * from orders


        and number like concat('%',#{number},'%')


        and phone like concat('%',#{phone},'%')


        and user_id = #{userId}


        and status = #{status}


        and store_id = #{storeId}


        and pet_id = #{petId}


        and service_date = #{serviceDate}


        and order_time >= #{beginTime}


        and order_time <= #{endTime}


order by order_time desc

select sum(amount) from orders


        and order_time > #{begin}


        and order_time < #{end}


        and status = #{status}

select count(id) from orders


        and order_time > #{begin}


        and order_time < #{end}


        and status = #{status}

select od.name, sum(od.number) number from order_detail od,orders o where od.order_id = o.id and o.status = 5
and o.order_time > #{begin}
and o.order_time < #{end}
group by od.name order by number desc limit 0,10
